-- Módulo 49: retornos físicos manuales, sin movimientos de inventario.
CREATE TABLE "RetornosLogisticos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Codigo" varchar(20) NOT NULL CHECK ("Codigo" = btrim("Codigo") AND length("Codigo") > 0),
    "ReferenciaOrigen" varchar(40) NOT NULL CHECK ("ReferenciaOrigen" = btrim("ReferenciaOrigen") AND length("ReferenciaOrigen") > 0),
    "Contraparte" varchar(200) NOT NULL CHECK ("Contraparte" = btrim("Contraparte") AND length("Contraparte") > 0),
    "PuntoRecogida" varchar(200) NOT NULL CHECK ("PuntoRecogida" = btrim("PuntoRecogida") AND length("PuntoRecogida") > 0),
    "PuntoRecepcion" varchar(200) NOT NULL CHECK ("PuntoRecepcion" = btrim("PuntoRecepcion") AND length("PuntoRecepcion") > 0),
    "Descripcion" varchar(200) NOT NULL CHECK ("Descripcion" = btrim("Descripcion") AND length("Descripcion") > 0),
    "Unidad" varchar(20) NOT NULL CHECK ("Unidad" = btrim("Unidad") AND length("Unidad") > 0),
    "Tipo" varchar(20) NOT NULL CHECK ("Tipo" IN ('Pallet','Retornable','DevolucionRuta')),
    "FechaProgramada" timestamptz NOT NULL,
    "CantidadProgramada" numeric(12,3) NOT NULL CHECK ("CantidadProgramada" BETWEEN 0.001 AND 999999999.999),
    "Observaciones" varchar(500),
    "Estado" varchar(15) NOT NULL DEFAULT 'Programado',
    "CantidadRecogida" numeric(12,3) CHECK ("CantidadRecogida" > 0 AND "CantidadRecogida" <= "CantidadProgramada"),
    "CantidadRecibida" numeric(12,3) CHECK ("CantidadRecibida" > 0 AND "CantidadRecibida" <= "CantidadRecogida"),
    "FechaRecogida" timestamptz,
    "FechaRecepcion" timestamptz,
    "FechaCancelacion" timestamptz,
    "ResponsableRecogida" varchar(100),
    "ResponsableRecepcion" varchar(100),
    "MotivoCancelacion" varchar(500),
    CONSTRAINT "CK_RetornosLogisticos_Estado" CHECK (
       ("Estado" = 'Programado' AND "CantidadRecogida" IS NULL AND "FechaRecogida" IS NULL AND "ResponsableRecogida" IS NULL AND "CantidadRecibida" IS NULL AND "FechaRecepcion" IS NULL AND "ResponsableRecepcion" IS NULL AND "FechaCancelacion" IS NULL AND "MotivoCancelacion" IS NULL) OR
       ("Estado" = 'Recogido' AND "CantidadRecogida" IS NOT NULL AND "FechaRecogida" IS NOT NULL AND length(btrim(coalesce("ResponsableRecogida",''))) > 0 AND "CantidadRecibida" IS NULL AND "FechaRecepcion" IS NULL AND "ResponsableRecepcion" IS NULL AND "FechaCancelacion" IS NULL AND "MotivoCancelacion" IS NULL) OR
       ("Estado" = 'Recibido' AND "CantidadRecogida" IS NOT NULL AND "FechaRecogida" IS NOT NULL AND length(btrim(coalesce("ResponsableRecogida",''))) > 0 AND "CantidadRecibida" IS NOT NULL AND "FechaRecepcion" IS NOT NULL AND length(btrim(coalesce("ResponsableRecepcion",''))) > 0 AND "FechaCancelacion" IS NULL AND "MotivoCancelacion" IS NULL) OR
       ("Estado" = 'Cancelado' AND "CantidadRecibida" IS NULL AND "FechaRecepcion" IS NULL AND "ResponsableRecepcion" IS NULL AND "FechaCancelacion" IS NOT NULL AND length(btrim(coalesce("MotivoCancelacion",''))) > 0 AND (("CantidadRecogida" IS NULL AND "FechaRecogida" IS NULL AND "ResponsableRecogida" IS NULL) OR ("CantidadRecogida" IS NOT NULL AND "FechaRecogida" IS NOT NULL AND length(btrim(coalesce("ResponsableRecogida",''))) > 0)))
    )
);
CREATE UNIQUE INDEX "IX_RetornosLogisticos_Codigo" ON "RetornosLogisticos" (lower(btrim("Codigo")));
